package com.hrm.service;import com.hrm.dao.EmployeeDAO;import com.hrm.model.Employee;import java.time.LocalDate;import java.util.List;public class EmployeeService{private final EmployeeDAO dao=new EmployeeDAO();public List<Employee>find(String q,int y)throws Exception{return dao.find(q,y);}public List<Employee>find(String q,int y,String d,String j,String s)throws Exception{return dao.find(q,y,d,j,s);}public List<String[]>departments()throws Exception{return dao.departments();}public List<String[]>jobs()throws Exception{return dao.jobs();}public int create(String n,String e,int j,LocalDate h,LocalDate rd,String s)throws Exception{return dao.insert(n,e,j,h,rd,s);}public void update(int id,String n,String e,int j,LocalDate h,LocalDate rd,String s)throws Exception{dao.update(id,n,e,j,h,rd,s);}public void delete(int id)throws Exception{dao.delete(id);}public void setAccountActive(int id,boolean a)throws Exception{dao.setAccountActive(id,a);}public boolean accountActive(int id)throws Exception{return dao.accountActive(id);}}